const $ = id => document.getElementById(id);
let selectedPortal="student", currentStudent=null, profileData=null, historyMode="planner", clockTimer=null;
const COURSES={"Aptitude":9,"Basic mathematics - Algebra":1,"C Programming":6,"C Programming Learning":4,"Communication":2,"Computer Networking":4,"Data Structure":11,"Database Programming":4,"Electrical Skills":1,"Electronics skill":2,"Group Discussion":1,"HTML / CSS":1,"Java Programming":4,"Java Script":1,"Linux":1,"Mechanical Manufacturing":2,"Programming C++":3,"Programming Python":4,"Version control - Git, Github":1};

function esc(v){return String(v??"").replace(/[&<>'"]/g,c=>({"&":"&amp;","<":"&lt;",">":"&gt;","'":"&#39;",'"':"&quot;"}[c]));}
function niceDate(v){if(!v)return "—";try{return new Date(v+"T00:00:00").toLocaleDateString("en-IN",{day:"2-digit",month:"short",year:"numeric"})}catch{return v}}
function showToast(msg){const t=$("toast");t.textContent=msg;t.classList.remove("show");void t.offsetWidth;t.classList.add("show");clearTimeout(showToast.t);showToast.t=setTimeout(()=>t.classList.remove("show"),2600)}
function countUp(el,target,dur){const start=performance.now();const from=parseInt(el.textContent)||0;const isPercent=el.dataset.suffix==="%"||String(target).includes(".");function tick(now){const t=Math.min((now-start)/(dur||800),1);const ease=1-Math.pow(1-t,3);const val=from+(target-from)*ease;el.textContent=isPercent?val.toFixed(1)+"%":Math.round(val);if(t<1)requestAnimationFrame(tick)}requestAnimationFrame(tick)}
function showSkeleton(el,count){if(!el)return;el.innerHTML=Array.from({length:count||3},()=>'<div class="skeleton-row"><div class="skeleton-circle skeleton"></div><div style="flex:1"><div class="skeleton skeleton-sm"></div><div class="skeleton"></div></div></div>').join("")}
async function api(url,opts={}){const r=await fetch(url,{credentials:"same-origin",...opts});let d={};try{d=await r.json()}catch{}if(!r.ok)throw new Error(d.message||"Something went wrong.");return d}
function hidePages(){["loginPage","createAccountPage","studentPage","adminPage"].forEach(id=>$(id)?.classList.add("hidden"))}
function choosePortal(p){selectedPortal=p;document.querySelectorAll(".portal-card").forEach((x,i)=>x.classList.toggle("active",(p==="student"&&i===0)||(p==="admin"&&i===1)));$("loginEyebrow").textContent=p==="student"?"STUDENT PORTAL":"ADMIN PORTAL";$("studentSignup").classList.toggle("hidden",p!=="student")}
function showCreateAccount(){hidePages();$("createAccountPage").classList.remove("hidden")}
function backToLogin(){hidePages();$("loginPage").classList.remove("hidden");choosePortal("student")}
async function signIn(){const email=$("loginEmail").value.trim(),password=$("loginPassword").value;if(!email||!password)return showToast("Enter email and password.");try{const d=await api(selectedPortal==="admin"?"/api/admin/login":"/api/login",{method:"POST",headers:{"Content-Type":"application/json"},body:JSON.stringify({email,password,remember:$("loginRemember").checked})});if(selectedPortal==="admin")openAdmin();else{currentStudent=d.student;openStudent();showToast("Login successful ✓")}}catch(e){showToast(e.message)}}
async function skipSignIn(){try{const d=await api(selectedPortal==="admin"?"/api/dev/skip-admin":"/api/dev/skip-student",{method:"POST",headers:{"Content-Type":"application/json"},body:"{}"});if(selectedPortal==="admin")openAdmin();else{currentStudent=d.student;openStudent();showToast("Dev skip ✓")}}catch(e){showToast(e.message)}}
async function checkDevSkip(){try{const d=await api("/api/dev/flag");const btn=$("devSkipBtn");if(btn)btn.style.display=d.enabled?"block":"none"}catch{$("devSkipBtn").style.display="none"}}
async function createAccount(){const ids=["signupEmail","signupPassword","signupConfirmPassword","signupRegisterNo","signupName","signupProgram","signupDepartment","signupYear","signupBatch","signupMobile"];const v=Object.fromEntries(ids.map(id=>[id,$(id).value.trim()]));if(!Object.values(v).every(Boolean))return showToast("Fill all account details.");if(v.signupPassword!==v.signupConfirmPassword)return showToast("Passwords do not match.");try{await api("/api/register",{method:"POST",headers:{"Content-Type":"application/json"},body:JSON.stringify({email:v.signupEmail,password:v.signupPassword,register_no:v.signupRegisterNo,name:v.signupName,program:v.signupProgram,department:v.signupDepartment,year:v.signupYear,batch:v.signupBatch,mobile:v.signupMobile,course:`${v.signupProgram}-${v.signupDepartment}`})});showToast("Account created ✓ Please sign in.");backToLogin();$("loginEmail").value=v.signupEmail}catch(e){showToast(e.message)}}
async function logout(){try{await api("/api/logout",{method:"POST"})}catch{}currentStudent=null;profileData=null;hidePages();$("loginPage").classList.remove("hidden");choosePortal("student");showToast("Logged out.")}
function toggleTheme(){const cur=document.documentElement.dataset.theme==="dark"?"light":"dark";document.documentElement.dataset.theme=cur;document.body.classList.toggle("dark",cur==="dark");localStorage.setItem("eliteTheme",cur)}
function applyTheme(){const saved=localStorage.getItem("eliteTheme");if(saved){document.documentElement.dataset.theme=saved;document.body.classList.toggle("dark",saved==="dark")}}
function startClock(){clearInterval(clockTimer);const tick=()=>{const n=new Date(),dt=n.toLocaleDateString("en-IN",{weekday:"short",day:"2-digit",month:"short",year:"numeric"}),tm=n.toLocaleTimeString("en-IN",{hour:"2-digit",minute:"2-digit",second:"2-digit",hour12:false});["todayDate","plannerDate","psDate"].forEach(id=>$(id)&&($(id).textContent=dt));["todayTime","liveClock","adminClock"].forEach(id=>$(id)&&($(id).textContent=tm))};tick();clockTimer=setInterval(tick,1000)}
function openStudent(){hidePages();$("studentPage").classList.remove("hidden");startClock();loadStudent()}
function openAdmin(){hidePages();$("adminPage").classList.remove("hidden");startClock();loadAdmin()}

function buildCourseOptions(id,includeBlank=true){const s=$(id);s.innerHTML=(includeBlank?'<option value="">Select FXEC Course</option>':"")+Object.keys(COURSES).map(c=>`<option value="${esc(c)}">${esc(c)}</option>`).join("")}
function fillLevels(id,course){const s=$(id),n=COURSES[course]||0;s.innerHTML=n?'<option value="">Select level</option>'+Array.from({length:n},(_,i)=>`<option value="L${i+1}">Level ${i+1}</option>`).join(""):'<option value="">Select course first</option>'}
function updatePSLevels(){fillLevels("psLevel",$("psCourse").value)}
function updateVerifyLevels(){fillLevels("verifyLevel",$("verifyCourse").value)}

function parseVenue(v){if(!v)return{type:"",value:""};if(v==="out")return{type:"out",value:""};if(v.startsWith("out:"))return{type:"out",value:v.slice(4)};if(v.startsWith("in:")){const rest=v.slice(3);if(["Elite - Lab 1","Elite - Lab 2","Elite - Lab 3"].includes(rest))return{type:"in",value:rest};return{type:"in",value:"Other",other:rest}}return{type:"in",value:v}}
window.__venueType={};
function setVenueType(h,type,btn){window.__venueType[h]=type;const cell=btn.closest(".planner-cell");const toggle=cell.querySelector(".venue-toggle");toggle.querySelectorAll(".venue-btn").forEach(b=>b.classList.remove("active"));btn.classList.add("active");const vr=cell.querySelector(".venue-row");const old=vr.querySelector(".venue-select,.venue-other,.venue-text");if(old)old.remove();if(type==="in"){const sel=document.createElement("select");sel.id=`v${h}lab`;sel.className="venue-select";sel.innerHTML=`<option value="">Select venue</option><option value="Elite - Lab 1">Elite - Lab 1</option><option value="Elite - Lab 2">Elite - Lab 2</option><option value="Elite - Lab 3">Elite - Lab 3</option><option value="Other">Other</option>`;sel.onchange=function(){onLabSelect(h,this)};vr.appendChild(sel)}else{const inp=document.createElement("input");inp.id=`v${h}out`;inp.className="venue-text";inp.maxLength=100;inp.placeholder="Enter venue";vr.appendChild(inp)}document.dispatchEvent(new Event("input"))}
function onLabSelect(h,sel){const cell=sel.closest(".planner-cell");const old=cell.querySelector(".venue-other");if(old)old.remove();if(sel.value==="Other"){const inp=document.createElement("input");inp.id=`v${h}other`;inp.className="venue-other";inp.maxLength=100;inp.placeholder="Enter venue name";sel.parentNode.appendChild(inp)}document.dispatchEvent(new Event("input"))}
function getVenueValue(h){const type=window.__venueType[h]||"in";if(type==="out"){const el=$(`v${h}out`);return el?"out:"+el.value.trim():":out"}const lab=$(`v${h}lab`);if(!lab||!lab.value)return"";if(lab.value==="Other"){const other=$(`v${h}other`);return other?"in:"+other.value.trim():"in:"}return "in:"+lab.value}
function renderPlanner(p){const hrs=[p?.h1,p?.h2,p?.h3,p?.h4,p?.h5,p?.h6,p?.h7];const vrs=[p?.v1,p?.v2,p?.v3,p?.v4,p?.v5,p?.v6,p?.v7];const labs=["Elite - Lab 1","Elite - Lab 2","Elite - Lab 3"];const taskCount=hrs.filter(h=>h&&h.trim()).length;const readyCount=taskCount;const pct=Math.round(readyCount/7*100);const readyLabel=`${readyCount}/7 hours planned`;const readyHtml=`<div class="plan-ready"><div class="plan-ready-fill"><i id="planReadyFill" style="width:0%"></i></div><span>${readyLabel}</span></div>`;$("plannerReady").innerHTML=readyHtml;$("plannerGrid").innerHTML=hrs.map((h,i)=>{const v=parseVenue(vrs[i]||"");const isIn=v.type==="in";const isOther=isIn&&v.value==="Other";const outText=isIn?"":v.value;const labSel=isIn?v.value:"";const hasTask=h&&h.trim();const hasVenue=!!(vrs[i]&&vrs[i].trim());const glowClass=(hasTask&&hasVenue)?" has-task":"";return`<div class="planner-cell${glowClass}"><div class="planner-label">H${i+1}</div><input id="h${i+1}" maxlength="120" value="${esc(h||"")}" placeholder="Task for hour ${i+1}"><div class="venue-row"><div class="venue-toggle"><button class="venue-btn${isIn?" active":""}" onclick="setVenueType(${i+1},'in',this)">In college</button><button class="venue-btn${!isIn&&v.type?" active":""}" onclick="setVenueType(${i+1},'out',this)">Out of college</button></div>${isIn?`<select id="v${i+1}lab" onchange="onLabSelect(${i+1},this)" class="venue-select"><option value=""${!labSel?" selected":""}>Select venue</option>${labs.map(l=>`<option value="${esc(l)}"${labSel===l?" selected":""}>${esc(l)}</option>`).join("")}<option value="Other"${isOther?" selected":""}>Other</option></select>${isOther?`<input id="v${i+1}other" maxlength="100" value="${esc(v.other||"")}" placeholder="Enter venue name" class="venue-other">`:``}`:`<input id="v${i+1}out" maxlength="100" value="${esc(outText)}" placeholder="Enter venue" class="venue-text">`}</div></div>`}).join("");requestAnimationFrame(()=>requestAnimationFrame(()=>{const f=$("planReadyFill");if(f)f.style.width=pct+"%"}))}
function renderTodayPlan(p){
if(!p){$("todayPlan").innerHTML='<div class="empty-state">No plan for today yet. Set tomorrow\u2019s plan so it\u2019s ready for you.</div>';return}
const hrs=[p.h1,p.h2,p.h3,p.h4,p.h5,p.h6,p.h7];
const done=[p.h1d,p.h2d,p.h3d,p.h4d,p.h5d,p.h6d,p.h7d];
const vrs=[p.v1,p.v2,p.v3,p.v4,p.v5,p.v6,p.v7];
const doneCount=done.filter(Boolean).length;
const pct=Math.round(doneCount/7*100);
const nextIdx=done.findIndex(d=>!d);
const motivational=pct===100?"All 7 hours done. Elite discipline.":pct>=50?"More than halfway. Finish strong.":pct>0?"Good start. Keep the streak going.":"Begin your first hour now.";
const header=`<div class="exec-header${pct===100?' perfect':''}"><div class="exec-header-left"><h3 id="execCount">${doneCount}/7 hours</h3><div class="seg-bar" id="segBar">${Array.from({length:7},(_,i)=>`<div class="seg${i<doneCount?' filled':''}" data-seg="${i}"></div>`).join("")}</div></div><div class="exec-motivation" id="execMotivation">${motivational}</div></div>`;
const rows=hrs.map((v,i)=>{
const vd=parseVenue(vrs[i]||"");
const chipClass=vd.type==="out"?"venue-chip out-college":vd.type==="in"?"venue-chip in-college":"";
const venueLabel=vd.type==="out"?(vd.value?`<span class="${chipClass}">${esc(vd.value)}</span>`:`<span class="${chipClass}">Out of college</span>`):vd.value?(vd.value==="Other"&&vd.other?`<span class="${chipClass}">${esc(vd.other)}</span>`:`<span class="${chipClass}">${esc(vd.value)}</span>`):"";
const isNext=i===nextIdx;
return`<div class="today-row${done[i]?" is-done":""}${isNext?" today-next":""}"><span class="planner-label">H${i+1}</span><div class="today-text"><span class="task-name">${esc(v||"\u2014")}</span>${venueLabel?'<span class="today-venue">'+venueLabel+'</span>':''}</div>${isNext?'<span class="next-tag">UP NEXT</span>':''}<button class="hour-done" onclick="toggleHourDone(${i+1},this)" aria-label="Mark hour ${i+1} done">${done[i]?"\u2713 Completed":"Mark done"}</button></div>`;
}).join("");
$("todayPlan").innerHTML=`${header}<div class="today-list">${rows}</div>`;
requestAnimationFrame(()=>requestAnimationFrame(()=>{
const segs=document.querySelectorAll("#segBar .seg.filled");
segs.forEach((s,i)=>{s.style.animationDelay=i*.08+"s";s.classList.add("seg-pop")});
}));
}
async function toggleHourDone(h,btn){const row=btn.closest(".today-row");if(row&&row.classList.contains("is-done"))return;btn.disabled=true;try{const d=await api("/api/planner/complete",{method:"POST",headers:{"Content-Type":"application/json"},body:JSON.stringify({hour:h})});$("activityPoints").textContent=d.activity_points;if(row){row.classList.add("is-done");btn.textContent="\u2713 Completed";btn.classList.add("done-pop");row.classList.remove("today-next");const oldTag=row.querySelector(".next-tag");if(oldTag)oldTag.remove();const allRows=[...document.querySelectorAll(".today-row:not(.is-done)")];if(allRows.length){const next=allRows[0];next.classList.add("today-next");if(!next.querySelector(".next-tag")){const tag=document.createElement("span");tag.className="next-tag";tag.textContent="UP NEXT";next.prepend(tag)}}const doneCount=document.querySelectorAll(".today-row.is-done").length;const pct=Math.round(doneCount/7*100);const ec=$("execCount");if(ec)ec.textContent=`${doneCount}/7 hours`;const seg=document.querySelector(`.seg[data-seg="${h-1}"]`);if(seg)seg.classList.add("filled");const em=$("execMotivation");if(em)em.textContent=pct===100?"All 7 hours done. Elite discipline.":pct>=50?"More than halfway. Finish strong.":pct>0?"Good start. Keep the streak going.":"Begin your first hour now.";const hdr=$("todayPlan")?.querySelector(".exec-header");if(hdr){if(pct===100){hdr.classList.add("perfect")}else{hdr.classList.remove("perfect")}}}showToast(d.message)}catch(e){showToast(e.message)}btn.disabled=false}
async function savePlanner(){const body={};for(let i=1;i<=7;i++){body[`h${i}`]=$("h"+i).value.trim();body[`v${i}`]=getVenueValue(i)}for(let i=1;i<=7;i++){if(!body[`h${i}`])return showToast(`H${i} needs a task.`);if(!body[`v${i}`])return showToast(`H${i} needs a venue.`)}const btn=$("plannerButton");btn.textContent="Saving...";btn.disabled=true;try{await api("/api/planner",{method:"POST",headers:{"Content-Type":"application/json"},body:JSON.stringify(body)});btn.textContent="Saved \u2713";const grid=$("plannerGrid");if(grid){grid.classList.remove("planner-save-pulse");void grid.offsetWidth;grid.classList.add("planner-save-pulse")}showToast("Tomorrow\u2019s plan saved \u2713");setTimeout(()=>{btn.textContent="Save tomorrow\u2019s plan \u2197";btn.disabled=false},1200);loadStudent()}catch(e){showToast(e.message);btn.textContent="Save tomorrow\u2019s plan \u2197";btn.disabled=false}}
function renderTaskLeaderboard(rows){$("taskLeaderboard").innerHTML=rows&&rows.length?`<div class="task-podium">${rows.slice(0,10).map(r=>`<div class="task-rank"><span class="rank-no">#${r.rank}</span><div><b>${esc(r.name)}</b><small class="subline">${esc(r.department)} · ${esc(r.year)}</small></div><strong>${r.points}</strong></div>`).join("")}</div>`:'<div class="empty-state">No task points yet.</div>'}
function renderMyTasks(tasks){window.__taskMap=Object.fromEntries((tasks||[]).map(t=>[t.id,t]));$("myTasks").innerHTML=(tasks||[]).length?`<div class="task-list-wrap">${tasks.map(t=>{const badge=t.status==="submitted"?`<span class="badge badge-warn">Awaiting verification</span>`:(t.status==="approved"?`<span class="badge badge-ok">Approved \u2713</span>`:`<button class="primary-btn sm" onclick="openTaskModal(${t.id})">Submit proof \u2197</button>`);return `<div class="task-item ${t.status||"assigned"}"><div class="task-item-head"><div><b>${esc(t.title)}</b><small class="subline">${esc(t.frequency)} \u00b7 Due ${niceDate(t.deadline)}</small></div><span class="task-points">+${t.points} pts</span></div><p class="muted">${esc(t.description)}</p>${badge}</div>`}).join("")}</div>`:'<div class="empty-state">No tasks assigned yet.</div>'}
let activeTaskId=null;
function openTaskModal(id){activeTaskId=id;const t=window.__taskMap?window.__taskMap[id]||{}:{};$("taskModalTitle").textContent=t.title||"Task";$("taskModalDesc").textContent=t.description||"";$("taskModalPoints").textContent="+"+(t.points||0)+" pts";$("taskModalDue").textContent=niceDate(t.deadline);$("taskProofFile").value="";$("taskProofNote").value="";$("taskModal").classList.remove("hidden")}
function closeTaskModal(){$("taskModal").classList.add("hidden")}
async function submitTaskProof(){const file=$("taskProofFile").files[0];const note=$("taskProofNote").value.trim();if(!file)return showToast("Attach a proof file.");const fd=new FormData();fd.append("note",note);fd.append("file",file);try{await api(`/api/tasks/${activeTaskId}/submit`,{method:"POST",body:fd});closeTaskModal();showToast("Proof submitted — awaiting verification.");loadMyTasks()}catch(e){showToast(e.message)}}
async function loadMyTasks(){try{const d=await api("/api/tasks");renderTaskLeaderboard(d.leaderboard);renderMyTasks(d.tasks)}catch(e){}}

async function savePS(){const body={course:$("psCourse").value,level:$("psLevel").value,status:$("psStatus").value,attempt_no:$("psAttempt").value,score:$("psScore").value};if(!body.course||!body.level||!body.attempt_no||body.score==="")return showToast("Fill course, level, attempt and score.");try{await api("/api/ps",{method:"POST",headers:{"Content-Type":"application/json"},body:JSON.stringify(body)});showToast("PS report saved — awaiting verification.");$("psAttempt").value="";$("psScore").value="";loadStudent()}catch(e){showToast(e.message)}}
async function submitVerification(){const body={course:$("verifyCourse").value,level:$("verifyLevel").value,proof_note:"Completed before this dashboard",proof_link:""};if(!body.course||!body.level)return showToast("Select a course and level.");const btn=document.querySelector("[onclick='submitVerification()']");if(btn){btn.textContent="Sending...";btn.disabled=true}try{await api("/api/progress-request",{method:"POST",headers:{"Content-Type":"application/json"},body:JSON.stringify(body)});showToast("Sent to Admin \u2713");$("verifyCourse").value="";$("verifyLevel").innerHTML='<option value="">Select course first</option>';const list=$("verificationStatus");if(list){const empty=list.querySelector(".empty-state");if(empty)empty.remove();const row=document.createElement("div");row.className="request-item";row.style.animation="fadeSlideIn .3s cubic-bezier(.22,1,.36,1) both";row.innerHTML=`<div><b>${esc(body.course)} \u00b7 L${body.level}</b><small>Completed before this dashboard</small></div><span class="badge badge-warn">Pending</span>`;list.prepend(row)}if(btn){btn.textContent="Send to Admin \u2197";btn.disabled=false}}catch(e){showToast(e.message);if(btn){btn.textContent="Send to Admin \u2197";btn.disabled=false}}}

function renderStats(st){const items=[["Verified levels",`${st.completed_levels}/${st.total_levels}`],["Overall progress",`${st.overall_progress}%`],["Current streak",`🔥 ${st.current_streak??st.streak?.current??0}`],["Reported PS",st.ps_submissions],["Pending",st.pending_ps],["Planner days",st.planner_days]];$("studentStats").innerHTML=items.map((x,i)=>`<div class="metric" style="animation:fadeSlideIn .35s cubic-bezier(.22,1,.36,1) ${i*.06}s both"><span>${x[0]}</span><strong data-countup="${(x[1]||"").replace(/[^0-9.]/g,"")}">${x[1]}</strong></div>`).join("");const p=Number(st.overall_progress)||0;$("progressDonut").style.setProperty("--p",`${Math.min(100,p)}%`);const dv=$("donutValue");if(dv){dv.dataset.countup=p;dv.textContent="0%"}const ap=$("activityPoints");if(ap){ap.dataset.countup=st.activity_points||0;ap.textContent="0"}$("[data-countup]").forEach(el=>{const v=parseFloat(el.dataset.countup);if(!isNaN(v))countUp(el,v,800)});$("motivationTitle").textContent=p>=75?"Elite momentum. Keep pushing.":p>=40?"You're building real momentum.":p>0?"Your progress has started.":"Start your first verified level.";$("motivationText").textContent=p>=75?"Protect the streak and finish the remaining levels.":"Daily work + verified completion = trusted progress."}
function renderMatrix(rows){
window.__matrixRows=rows||[];
const box=$("advancedSkillMatrix");
if(box)box.style.display="grid";
const hasProgress=window.__matrixRows.filter(c=>c.progress>0);
const btn=$("matrixToggle");
if(btn)btn.textContent=window.__matrixExpanded?"Hide courses":"Show all courses ("+window.__matrixRows.length+")";
if(!window.__matrixExpanded){
const shown=hasProgress.length?hasProgress:window.__matrixRows.slice(0,3);
$("advancedSkillMatrix").innerHTML=shown.map(c=>`<div class="course-card"><div class="course-card-head"><div><strong>${esc(c.course)}</strong><span>${c.completed_levels} of ${c.total_levels} levels</span></div><b>${c.progress}%</b></div><div class="bar"><i style="width:0%" data-target="${c.progress}"></i></div></div>`).join("")||'<div class="empty-state">No verified levels yet. Start learning.</div>';
}else{
$("advancedSkillMatrix").innerHTML=window.__matrixRows.map(c=>`<div class="course-card"><div class="course-card-head"><div><strong>${esc(c.course)}</strong><span>${c.completed_levels} of ${c.total_levels} levels completed</span></div><b>${c.progress}%</b></div><div class="level-track">${Array.from({length:c.total_levels},(_,n)=>`<i class="${n<c.completed_levels?'done':''}">${n+1}</i>`).join("")}</div><div class="bar"><i style="width:0%" data-target="${c.progress}"></i></div></div>`).join("")||'<div class="empty-state">No verified levels yet. Start learning.</div>';
}
requestAnimationFrame(()=>requestAnimationFrame(()=>{document.querySelectorAll(".advanced-matrix .bar i[data-target]").forEach(el=>{el.style.width=el.dataset.target+"%"})}));
}
function toggleMatrix(){window.__matrixExpanded=!window.__matrixExpanded;renderMatrix(window.__matrixRows||[])}
function renderLeaderboard(rows){const top=(rows||[]).slice(0,3);const rest=(rows||[]).slice(3);const sid=currentStudent?.id;function moveIcon(r){if(!r.movement||r.movement==="same")return"";if(r.movement==="new")return'<span class="move-badge move-new">NEW</span>';return r.movement==="up"?`<span class="move-badge move-up">▲${r.delta||''}</span>`:`<span class="move-badge move-down">▼${r.delta||''}</span>`}$("leaderboard").innerHTML=(rows||[]).length?`<div class="podium">${top.map((r,i)=>`<div class="podium-card rank-${i+1}"><span>${["🥇","🥈","🥉"][i]}</span><b>${esc(r.name)}${sid&&r.student_id===sid?' <span class="row-you-badge">YOU</span>':''}</b>${moveIcon(r)}<strong>${r.progress}%</strong><small>${r.levels} verified levels · 🔥 ${r.streak}</small></div>`).join("")}</div><div class="table-wrap"><table class="data-table"><thead><tr><th>Rank</th><th>Student</th><th>Progress</th><th>Levels</th><th>Streak</th></tr></thead><tbody>${rest.map(r=>`<tr class="${sid&&r.student_id===sid?'row-you':''}"><td>#${r.rank} ${moveIcon(r)}</td><td><b>${esc(r.name)}</b><small class="subline">${esc(r.department)} · ${esc(r.year)}</small></td><td><b class="green-text">${r.progress}%</b></td><td>${r.levels}</td><td>🔥 ${r.streak}</td></tr>`).join("")}</tbody></table></div>`:'<div class="empty-state">Leaderboard will appear after verified progress is recorded.</div>'}
