function renderGreeting(){if(!currentStudent)return;const h=new Date().getHours();const name=currentStudent.name.split(" ")[0];const emoji=h<12?"☀️":h<17?"🌤️":"🌙";const greeting=h<12?"Good morning":h<17?"Good afternoon":"Good evening";const el=$("welcomeName");if(el)el.textContent=`${greeting}, ${name} ${emoji}`;const tag=$("welcomeTagline");if(tag&&!window.__tagTyped){window.__tagTyped=true;typeWriter(tag,"Small wins daily. Verified progress compounds.")}}
function typeWriter(el,text,cb){el.textContent="";const caret=document.createElement("span");caret.className="typewriter-caret";el.appendChild(caret);let i=0;function tick(){if(i<text.length){caret.before(document.createTextNode(text[i]));i++}else{caret.remove();if(cb)cb();return}setTimeout(tick,32)}tick()}
function renderGlanceStrip(d,slot){const el=$("glanceStrip");if(!el||!d)return;const hours=[d.today.planner?.h1d,d.today.planner?.h2d,d.today.planner?.h3d,d.today.planner?.h4d,d.today.planner?.h5d,d.today.planner?.h6d,d.today.planner?.h7d];const doneCount=hours.filter(Boolean).length;const slotLabel=slot?(slot.my_booking?"Booked":slot.window_open?"Open":"Closed"):"\u2014";const slotColor=slot?(slot.my_booking?"green":slot.window_open?"amber":"red"):"amber";const booked=slot?slot.booked:0;const cap=slot?slot.capacity:10;const capPct=Math.round(booked/cap*100);const capClass=capPct<50?"low":capPct<90?"med":"high";el.innerHTML=[`<div class="glance-item"><span>H done</span>${doneCount}/7</div>`,`<div class="glance-item"><div class="glance-dot ${slotColor}"></div><span>Slot</span>${slotLabel}</div><div class="slot-cap" style="width:80px"><div class="slot-cap-fill ${capClass}" style="width:${capPct}%"></div></div>`,`<div class="glance-item"><span>Points</span>${d.stats.activity_points??0}</div>`].join("")}

async function loadStudent(){showSkeleton($("todayPlan"),3);showSkeleton($("plannerGrid"),3);try{const results=await Promise.allSettled([api("/api/dashboard"),api("/api/profile"),api("/api/support"),api("/api/ps-leaderboard"),api("/api/slot/status"),api("/api/clearance-history"),api("/api/course-matrix")]);const d=results[0].value;const p=results[1].status==='fulfilled'?results[1].value:null;const s=results[2].status==='fulfilled'?results[2].value:null;const lb=results[3].status==='fulfilled'?results[3].value:null;const slot=results[4].status==='fulfilled'?results[4].value:null;const clear=results[5].status==='fulfilled'?results[5].value:null;const course=results[6].status==='fulfilled'?results[6].value:null;if(p){profileData=p;currentStudent=p.student}renderGreeting();if(d)renderPlanner(d.tomorrow?.planner);if(d)renderTodayPlan(d.today?.planner);if(d)renderGlanceStrip(d,slot);if(s)renderSupport(s.requests);if(d)$("activityPoints").textContent=d.stats.activity_points||0;if(p)renderMyTaskScore(p.stats.task_points);if(lb)renderPSLeaderboard(lb.leaderboard);if(slot)renderSlotStatus(slot);if(clear)renderClearanceHistory(clear);if(course)renderMatrix(course.courses);loadMyTasks()}catch(e){showToast(e.message)}}
