let currentPsMonth = new Date().toISOString().slice(0, 7);

async function renderPSMonthlyGraph(month){
if(month)currentPsMonth=month;
const m=currentPsMonth;
const el=$("psMonthlyGraph");
if(!el)return;
const label=$("psGraphMonth");
const dObj=new Date(m+"-01");
const monthName=dObj.toLocaleDateString("en-US",{month:"long",year:"numeric"});
if(label)label.textContent=monthName;
try{
const d=await api(`/api/ps-monthly?month=${m}`);
const daysInMonth=d.days_in_month||30;
const daily=d.daily||{};
const pts=[];
let cumVerified=0;
const width=Math.max(500,el.clientWidth||600);
const height=140;
const padding=35;
const chartW=width-padding*2;
const chartH=height-padding*2;
for(let day=1;day<=daysInMonth;day++){
const dateStr=`${m}-${String(day).padStart(2,'0')}`;
const items=daily[dateStr]||[];
const verified=items.filter(i=>i.verification_status==='Verified'||i.status==='Completed').length;
const pending=items.filter(i=>i.verification_status==='Pending').length;
cumVerified+=verified;
pts.push({day,dateStr,verified,pending,total:cumVerified});
}
const maxVal=Math.max(10,Math.max(...pts.map(p=>p.total)));
const pathD=pts.map((p,i)=>{
const x=padding+(i/(daysInMonth-1))*chartW;
const y=height-padding-(p.total/maxVal)*chartH;
return `${i===0?'M':'L'} ${x.toFixed(1)} ${y.toFixed(1)}`;
}).join(' ');
const areaD=pathD+` L ${(padding+chartW).toFixed(1)} ${(height-padding).toFixed(1)} L ${padding} ${(height-padding).toFixed(1)} Z`;
const circles=pts.filter(p=>p.verified>0||p.pending>0).map(p=>{
const i=p.day-1;
const x=padding+(i/(daysInMonth-1))*chartW;
const y=height-padding-(p.total/maxVal)*chartH;
const isPending=p.pending>0&&p.verified===0;
return `<circle cx="${x.toFixed(1)}" cy="${y.toFixed(1)}" r="4" class="ps-graph-dot${isPending?' pending':''}"><title>${p.dateStr}: ${p.verified} verified, ${p.pending} pending</title></circle>`;
}).join('');
const labels=[1,5,10,15,20,25,daysInMonth].map(day=>{
const i=day-1;
const x=padding+(i/(daysInMonth-1))*chartW;
return `<text x="${x.toFixed(1)}" y="${height-10}" class="ps-graph-label">${day}</text>`;
}).join('');
el.innerHTML=`<svg class="ps-graph-svg" viewBox="0 0 ${width} ${height}"><defs><linearGradient id="psGraphGrad" x1="0" y1="0" x2="0" y2="1"><stop offset="0%" stop-color="var(--accent)" stop-opacity="0.4"/><stop offset="100%" stop-color="var(--accent)" stop-opacity="0.0"/></linearGradient></defs><path class="ps-graph-area" d="${areaD}"/><path class="ps-graph-line" d="${pathD}"/>${circles}${labels}</svg>`;
}catch(e){
el.innerHTML='<div class="empty-state">Unable to load graph data.</div>';
}
}
function psMonthStep(dir){
const parts=currentPsMonth.split("-");
let yr=parseInt(parts[0],10)||0,mo=(parseInt(parts[1],10)||0)+dir;
if(mo<1){mo=12;yr--;}
if(mo>12){mo=1;yr++;}
currentPsMonth=`${yr}-${String(mo).padStart(2,'0')}`;
renderPSMonthlyGraph(currentPsMonth);
}
function renderSlotStatus(d){window.__slot=d;const today=d.now.slice(0,10);const my=d.my_booking,tb=d.today_booking;const unreported=(d.bookings||[]).filter(b=>b.slot_date<=today&&!b.report_status);$("slotWindowInfo").textContent=`Opens ${d.open_time} daily · ${d.target_date} · ${d.booked}/${d.capacity} booked`;$("slotBookingForm").classList.add("hidden");$("slotReportWrap").classList.add("hidden");$("slotMyBookings").innerHTML=(d.bookings||[]).length?(d.bookings||[]).map(b=>{const rs=b.report_status?`<span class="badge badge-ok">${b.report_status.replaceAll("_"," ")}</span>`:`<span class="badge badge-warn">not reported</span>`;return `<div class="slot-booking"><div><b>${esc(b.course)} · ${esc(b.level)}</b><small class="subline">${niceDate(b.slot_date)}</small></div>${rs}</div>`}).join(""):'<div class="empty-state">No slot bookings yet.</div>';let st="";if(d.blocked&&unreported.length){st+=`<div class="alert-warn">⚠️ Report your previous booked slot before booking a new one.</div>`;openReportForm(unreported[0].id,`${unreported[0].course} ${unreported[0].level} (${niceDate(unreported[0].slot_date)})`);$("slotStatus").innerHTML=st;return}if(tb&&!tb.report_status){st+=`<p class="muted">Your slot today is <b>${esc(tb.course)} ${esc(tb.level)}</b>.</p>`;openReportForm(tb.id,`${tb.course} ${tb.level} (today)`);$("slotStatus").innerHTML=st;return}if(my){st+=`<p class="muted">You are booked for <b>${esc(my.course)} ${esc(my.level)}</b> on ${niceDate(my.slot_date)}. Report after attending.</p>`}else if(d.window_open){$("slotBookingForm").classList.remove("hidden");buildCourseOptions("slotCourse");st+=`<p class="muted">Booking is <b>open</b> for ${niceDate(d.target_date)}. First ${d.capacity} students get allotted.</p>`}else if(!d.day_open){st+=`<p class="muted">Booking for this slot was <b>cancelled</b> by Admin.</p>`}else if(d.booked>=d.capacity){st+=`<p class="muted">This slot is <b>full</b> (${d.capacity}/${d.capacity}).</p>`}else{st+=`<p class="muted">Booking opens at <b>${d.open_time}</b> for tomorrow's slot.</p>`}$("slotStatus").innerHTML=st}
function openReportForm(id,label){window.__slotReportBookingId=id;$("slotReportLabel").textContent="Reporting for: "+label;$("slotReportStatus").value="completed";$("slotReportScore").value="";$("slotReportWrap").classList.remove("hidden")}
