function renderClearanceHistory(clear){const cleared=(clear.cleared||[]).map(x=>`<div class="clearance-row"><span class="badge badge-ok">CLEARED</span><div><b>${esc(x.course)} · ${esc(x.level)}</b><small class="subline">Cleared on ${niceDate(x.date)}</small></div></div>`).join("");const pend=(clear.pending||[]).map(x=>`<div class="clearance-row"><span class="badge badge-warn">WAITING</span><div><b>${esc(x.course)} · ${esc(x.level)}</b><small class="subline">Waiting for approval</small></div></div>`).join("");$("clearanceHistory").innerHTML=(cleared||pend)?`<div class="task-podium">${cleared}${pend}</div>`:'<div class="empty-state">No levels cleared yet.</div>'}

