async function loadPSUnreported(){const y=new Date();y.setDate(y.getDate()-1);const dy=y.getFullYear()+"-"+String(y.getMonth()+1).padStart(2,"0")+"-"+String(y.getDate()).padStart(2,"0");try{const d=await api(`/api/admin/slots/noshows?date=${dy}`);const list=d.names.length?d.names.map(n=>`<div class="clearance-row"><span class="badge badge-err">UNREPORTED</span><div><b>${esc(n)}</b></div></div>`).join(""):'<div class="empty-state">Everyone reported their booked slots.</div>';const wa=d.names.length?`<div class="whatsapp-box"><textarea id="psWaMsg" rows="5" readonly>${esc(d.message)}</textarea><div class="row-actions"><button class="primary-btn sm" onclick="copyText('psWaMsg')">Copy message</button><a class="ghost-btn sm" href="${esc(d.wa_link)}" target="_blank" rel="noopener">Open WhatsApp ↗</a></div></div>`:'';$("psUnreported").innerHTML=list+wa}catch(e){showToast(e.message)}}
async function loadPSTop5(){try{const d=await api("/api/admin/ps-progress?view=top");$("psTop5").innerHTML=d.students.slice(0,5).map(r=>`<div class="rank-row"><span class="rank-num">${r.rank}</span><div><b>${esc(r.name)}</b><small class="subline">${esc(r.department)} · ${esc(r.year)}</small></div><b class="green-text">${r.levels}</b></div>`).join("")||'<div class="empty-state">No verified PS progress yet.</div>'}catch(e){showToast(e.message)}}
function psRegStep(dir){if(!window.__regDate)return;const p=window.__regDate.split("-");const d=new Date(+p[0],+p[1]-1,+p[2]);d.setDate(d.getDate()+dir);window.__regDate=d.getFullYear()+"-"+String(d.getMonth()+1).padStart(2,"0")+"-"+String(d.getDate()).padStart(2,"0");loadPSRegister()}
async function loadPSRegister(){try{const d=await api(`/api/admin/slots/register?date=${window.__regDate}`);$("psRegDate").textContent=window.__regDate;$("psRegister").innerHTML=`<p class="muted">${d.booked_count} booked · ${d.reported} reported · ${d.total} students</p>`+`<div class="table-wrap"><table class="data-table"><thead><tr><th>Student</th><th>Register</th><th>Dept / Year</th><th>Course</th><th>Level</th><th>Status</th><th>Score</th></tr></thead><tbody>${d.rows.map(r=>{const status=r.status?`<span class="badge ${r.status==="completed"?"badge-ok":r.status==="not_attended"?"badge-err":"badge-warn"}">${esc(r.status.replaceAll("_"," "))}</span>`:(r.booked?'<span class="badge badge-warn">not reported</span>':'<span class="muted">—</span>');return `<tr class="${r.no_show?"row-noshows":""}"><td><b>${esc(r.name)}</b></td><td>${esc(r.register_no)}</td><td>${esc(r.department)} · ${esc(r.year)}</td><td>${esc(r.course)||"—"}</td><td>${esc(r.level)||"—"}</td><td>${status}</td><td>${r.score!==""?r.score:"—"}</td></tr>`}).join("")}</tbody></table></div>`}catch(e){showToast(e.message)}}
function exportPSRegister(){window.location.href=`/api/admin/slots/export?scope=day&date=${window.__regDate}`}
function copyText(id){const t=$(id);t.select();navigator.clipboard&&navigator.clipboard.writeText(t.value);showToast("Message copied ✓")}
function loadAdminSearchTab(){$("adminSearchDetail").innerHTML=""}
async function adminSearchGo(){const q=$("adminSearchInput").value.trim();if(!q)return showToast("Enter a name, register number, or department.");try{const d=await api(`/api/admin/students?q=${encodeURIComponent(q)}`);if(!d.students.length){$("adminSearchResults").innerHTML='<div class="empty-state">No students match your search.</div>';return}$("adminSearchResults").innerHTML=`<div class="search-results">${d.students.map(s=>`<button class="search-result" onclick="adminOpenSearch(${s.id},'${esc(s.register_no)}')"><div><b>${esc(s.name)}</b><small class="subline">${esc(s.register_no)} · ${esc(s.department)} · ${esc(s.year)}</small></div><span class="muted">${s.levels} levels · ${s.progress}%</span></button>`).join("")}</div>`}catch(e){showToast(e.message)}}
async function adminOpenSearch(id,reg){try{const d=await api("/api/admin/student/"+encodeURIComponent(reg));const s=d.student,st=d.stats,p=d.points;$("adminSearchDetail").innerHTML=`<section class="card"><div class="section-head"><div><p class="eyebrow">STUDENT PROFILE</p><h2>${esc(s.name)}</h2></div><span class="badge ${s.account_status==="Active"?"badge-ok":"badge-err"}">${esc(s.account_status)}</span></div>
   <div class="profile-details"><div><span>Register No</span><b>${esc(s.register_no)}</b></div><div><span>Email</span><b>${esc(s.email)}</b></div><div><span>Program</span><b>${esc(s.program)}</b></div><div><span>Department</span><b>${esc(s.department)}</b></div><div><span>Year</span><b>${esc(s.year)}</b></div><div><span>Batch</span><b>${esc(s.batch)}</b></div><div><span>Mobile</span><b>${esc(s.mobile)}</b></div><div><span>Course</span><b>${esc(s.course)}</b></div></div>
   <div class="two-col"><div class="mini-card"><span>ACTIVITY POINTS</span><b class="${p.activity_points<0?"danger-text":"green-text"}">${p.activity_points}</b><small>rank #${p.activity_rank??"—"}</small></div><div class="mini-card"><span>TASK POINTS</span><b class="green-text">${p.task_points}</b><small>rank #${p.task_rank??"—"}</small></div></div>
   <div class="admin-actions"><button class="primary-btn" onclick="adminResetPassword(${s.id})">Reset password</button><button class="icon-btn" onclick="adminChangeName(${s.id},'${reg}','${esc(s.name)}')">Change name</button><button class="icon-btn" onclick="adminAcademic(${s.id},'${reg}','${esc(s.program)}','${esc(s.department)}','${esc(s.year)}','${esc(s.batch)}')">Academic details</button><button class="icon-btn" onclick="adminToggleStatus(${s.id},'${reg}','${s.account_status}')">${s.account_status==="Active"?"Deactivate":"Activate"}</button></div>
   <h3 class="section-head sub">Verified progress</h3><div class="advanced-stats"><div class="metric"><span>Verified levels</span><strong>${st.completed_levels}/${st.total_levels}</strong></div><div class="metric"><span>Streak</span><strong>🔥 ${d.stats.current_streak}</strong></div><div class="metric"><span>PS reports</span><strong>${st.ps_submissions}</strong></div><div class="metric"><span>Pending</span><strong>${st.pending_ps}</strong></div></div>
   <h3 class="section-head sub">Planner history</h3><div class="table-wrap"><table class="data-table"><thead><tr><th>Date</th><th>H1</th><th>H2</th><th>H3</th><th>H4</th><th>H5</th><th>H6</th><th>H7</th></tr></thead><tbody>${d.planners.map(p=>`<tr><td>${niceDate(p.date)}</td>${[1,2,3,4,5,6,7].map(i=>`<td>${esc(p["h"+i]||"—")}</td>`).join("")}</tr>`).join("")}</tbody></table></div>
   <h3 class="section-head sub">PS reports</h3><div class="table-wrap"><table class="data-table"><thead><tr><th>Date</th><th>Course</th><th>Level</th><th>Status</th><th>Score</th><th>Verification</th></tr></thead><tbody>${d.ps_progress.map(r=>`<tr><td>${niceDate(r.date)}</td><td>${esc(r.course)}</td><td>${esc(r.level)}</td><td>${esc(r.status)}</td><td>${r.score}</td><td><span class="badge ${r.verification_status==="Verified"?"badge-ok":r.verification_status==="Rejected"?"badge-err":"badge-warn"}">${esc(r.verification_status)}</span></td></tr>`).join("")}</tbody></table></div></section>`}catch(e){showToast(e.message)}}
function adminSearchGoResults(){}
function reportDeptOptions(){const depts=["CSE","ECE","EEE","MECH","CIVIL","IT","AIDS","CSBS","AIML"];$("reportDept").innerHTML=depts.map(d=>`<option value="${d}">${d}</option>`).join("")}
function switchReportView(view,btn){document.querySelectorAll("#psViewSeg .seg-btn").forEach(x=>x.classList.remove("active"));btn.classList.add("active");$("reportDept").style.display=view==="dept"?"":"none";loadPSProgressView()}
function loadReports(){populateReportDepts();loadReportTask();loadReportPS()}
function populateReportDepts(){["repTaskDept","repPSDept"].forEach(id=>{const s=$(id);const cur=s.value;s.innerHTML='<option value="">All departments</option>'+["CSE","ECE","EEE","MECH","CIVIL","IT","AIDS","CSBS","AIML"].map(d=>`<option value="${d}">${d}</option>`).join("");s.value=cur})}
async function loadReportTask(){const sort=$("repTaskSort").value,dept=$("repTaskDept").value;try{const d=await api(`/api/admin/report-taskpoints?sort=${sort}&dept=${encodeURIComponent(dept)}`);$("reportTask").innerHTML=`<div class="table-wrap"><table class="data-table"><thead><tr><th>Rank</th><th>Student</th><th>Dept / Year</th><th>Tasks completed</th><th>Points</th></tr></thead><tbody>${d.rows.map(r=>`<tr><td>#${r.rank}</td><td><b>${esc(r.name)}</b><small class="subline">${esc(r.register_no)}</small></td><td>${esc(r.department)} · ${esc(r.year)}</td><td>${r.tasks_completed}</td><td><b class="green-text">${r.points}</b></td></tr>`).join("")}</tbody></table></div>`}catch(e){showToast(e.message)}}
async function loadReportPS(){const sort=$("repPSSort").value,dept=$("repPSDept").value;try{const d=await api(`/api/admin/report-psprogress?sort=${sort}&dept=${encodeURIComponent(dept)}`);$("reportPS").innerHTML=`<div class="table-wrap"><table class="data-table"><thead><tr><th>Rank</th><th>Student</th><th>Dept / Year</th><th>Levels</th><th class="tier-cell">L1</th><th class="tier-cell">L2</th><th class="tier-cell">L3</th><th class="tier-cell">L4</th></tr></thead><tbody>${d.rows.map(r=>`<tr><td>#${r.rank}</td><td><b>${esc(r.name)}</b><small class="subline">${esc(r.register_no)}</small></td><td>${esc(r.department)} · ${esc(r.year)}</td><td><b class="green-text">${r.levels_completed}</b></td>${r.tiers.map(t=>`<td class="tier-cell ${t.done?"tier-done":"tier-miss"}">${t.done?"✓":"✗"}</td>`).join("")}</tr>`).join("")}</tbody></table></div>`}catch(e){showToast(e.message)}}
function exportReport(which){const sort=which==="task"?$("repTaskSort").value:$("repPSSort").value;const dept=which==="task"?$("repTaskDept").value:$("repPSDept").value;window.location.href=`/api/admin/report-${which==="task"?"taskpoints":"psprogress"}/export?sort=${sort}&dept=${encodeURIComponent(dept)}`}
async function loadPSProgressView(){const active=document.querySelector("#psViewSeg .seg-btn.active");const view=active?active.textContent.replaceAll(" ","").toLowerCase().replace("bydepartment","dept").replace("top25","top").replace("bottom15","bottom"):"dept";let url=`/api/admin/ps-progress?view=${view}`;if(view==="dept")url+=`&dept=${encodeURIComponent($("reportDept").value)}`;try{const d=await api(url);$("psProgressReport").innerHTML=d.students.length?`<div class="table-wrap"><table class="data-table"><thead><tr><th>Rank</th><th>Student</th><th>Register</th><th>Dept / Year</th><th>Progress</th><th>Levels</th><th>Streak</th></tr></thead><tbody>${d.students.map(r=>`<tr><td>#${r.rank}</td><td><b>${esc(r.name)}</b></td><td>${esc(r.register_no)}</td><td>${esc(r.department)} · ${esc(r.year)}</td><td><b class="green-text">${r.progress}%</b></td><td>${r.levels}</td><td>🔥 ${r.streak}</td></tr>`).join("")}</tbody></table></div>`:'<div class="empty-state">No active students in this view.</div>'}catch(e){showToast(e.message)}}
async function loadOverallReport(){const sort=$("reportSort").value;try{const d=await api(`/api/admin/report?sort=${sort}`);$("overallReport").innerHTML=d.students.length?`<div class="table-wrap"><table class="data-table"><thead><tr><th>Rank</th><th>Student</th><th>Register</th><th>Dept / Year</th><th>Progress</th><th>Levels</th><th>Streak</th></tr></thead><tbody>${d.students.map(r=>`<tr><td>#${r.rank}</td><td><b>${esc(r.name)}</b></td><td>${esc(r.register_no)}</td><td>${esc(r.department)} · ${esc(r.year)}</td><td><b class="green-text">${r.progress}%</b></td><td>${r.levels}</td><td>🔥 ${r.streak}</td></tr>`).join("")}</tbody></table></div>`:'<div class="empty-state">No active students to report.</div>'}catch(e){showToast(e.message)}}
function exportExcel(){const sort=$("reportSort").value;window.location.href=`/api/admin/report/export?sort=${sort}`}

function taskSection(which,btn){document.querySelectorAll("#taskSeg .seg-btn").forEach(x=>x.classList.remove("active"));btn.classList.add("active");["taskAssign","taskVerify"].forEach(id=>$(id).classList.add("hidden"));$(which==="assign"?"taskAssign":"taskVerify").classList.remove("hidden");if(which==="assign"){loadAdminTasks();populateTaskStudents();}if(which==="verify")loadAdminTaskSubmissions()}
async function populateTaskStudents(){try{const d=await api("/api/admin/students?q=");$("taskStudent").innerHTML=d.students.map(s=>`<option value="${s.id}">${esc(s.name)} · ${esc(s.register_no)}</option>`).join("")}catch(e){}}
function toggleTaskTarget(){$("taskStudentWrap").classList.toggle("hidden",$("taskTarget").value!=="student")}
function setDeadlineFromDays(){const n=+$("taskDays").value;window.taskDeadline=new Date(Date.now()+n*864e5).toISOString().slice(0,10);$("taskDate").value=window.taskDeadline}
function setDeadlineFromDate(){const v=$("taskDate").value;if(v){window.taskDeadline=v;$("taskDays").selectedIndex=0}}
async function createTask(){if(!window.taskDeadline)setDeadlineFromDays();const body={title:$("taskTitle").value.trim(),description:$("taskDescription").value.trim(),points:+$("taskPoints").value||0,frequency:$("taskFrequency").value,target_type:$("taskTarget").value,target_student_id:$("taskTarget").value==="student"?+$("taskStudent").value:null,deadline:window.taskDeadline};if(!body.title||!body.description)return showToast("Enter a title and description.");try{await api("/api/admin/tasks",{method:"POST",headers:{"Content-Type":"application/json"},body:JSON.stringify(body)});showToast("Task assigned ✓");$("taskTitle").value="";$("taskDescription").value="";$("taskPoints").value="";loadAdminTasks()}catch(e){showToast(e.message)}}
async function loadAdminTasks(){try{const [d,t]=await Promise.all([api("/api/admin/tasks"),api("/api/admin/tasks/leaderboard")]);$("adminTaskList").innerHTML=d.tasks.length?`<div class="table-wrap"><table class="data-table"><thead><tr><th>Task</th><th>Points</th><th>Freq</th><th>Deadline</th><th>Assigned</th><th>Pending</th><th>Done</th></tr></thead><tbody>${d.tasks.map(t=>`<tr><td><b>${esc(t.title)}</b><small class="subline">${esc(t.description||"")}</small></td><td>+${t.points}</td><td>${esc(t.frequency)}</td><td>${niceDate(t.deadline)}</td><td>${t.assigned}</td><td>${t.submitted}</td><td>${t.approved}</td></tr>`).join("")}</tbody></table></div>`:'<div class="empty-state">No tasks assigned yet.</div>';$("adminTaskTop5").innerHTML=t.leaderboard.slice(0,5).map(s=>`<div class="rank-row"><span class="rank-num">${s.rank}</span><div><b>${esc(s.name)}</b><small class="subline">${esc(s.department)} · ${esc(s.year)}</small></div><b class="green-text">${s.points}</b></div>`).join("")||'<div class="empty-state">No task points yet.</div>'}catch(e){showToast(e.message)}}
async function loadAdminTaskSubmissions(){try{const d=await api("/api/admin/tasks/submissions");$("adminTaskSubmissions").innerHTML=d.submissions.length?`<div class="queue-list">${d.submissions.map(s=>{const statusBadge=s.status==="pending"?`<span class="badge badge-warn">pending</span>`:s.status==="approved"?`<span class="badge badge-ok">approved</span>`:`<span class="badge badge-err">rejected</span>`;const review=s.status==="pending"?`<div class="row-actions"><button class="primary-btn sm" onclick="event.stopPropagation();reviewTaskSubmission(${s.id},'approved')">Approve ✓</button><button class="ghost-btn sm" onclick="event.stopPropagation();reviewTaskSubmission(${s.id},'rejected')">Reject</button></div>`:'';return `<div class="queue-item ${s.status==='pending'?'queue-pending':''}" onclick="toggleQueueDetail(this)"><div class="queue-row"><div><b>${esc(s.name)}</b><small class="subline">${esc(s.register_no)} · ${esc(s.title)} · +${s.points} pts</small></div>${statusBadge}</div><div class="queue-detail hidden"><p class="cell-note">${esc(s.note||"—")}</p>${s.file_path?`<a class="proof-link" href="${esc(s.file_path)}" target="_blank" rel="noopener">Open proof ↗</a>`:'<span class="muted">No file</span>'}<div class="queue-actions">${review}</div></div></div>`}).join("")}</div>`:'<div class="empty-state">No task submissions yet.</div>'}catch(e){showToast(e.message)}}
function toggleQueueDetail(el){el.querySelector(".queue-detail").classList.toggle("hidden")}
async function reviewTaskSubmission(id,decision){try{await api(`/api/admin/tasks/submissions/${id}`,{method:"POST",headers:{"Content-Type":"application/json"},body:JSON.stringify({decision})});showToast(decision==="approved"?"Approved — points awarded ✓":"Submission rejected.");loadAdminTaskSubmissions();loadAdminTaskTop5()}catch(e){showToast(e.message)}}
async function loadAdminTaskTop5(){try{const t=await api("/api/admin/tasks/leaderboard");const el=$("adminTaskTop5");if(el)el.innerHTML=t.leaderboard.slice(0,5).map(s=>`<div class="rank-row"><span class="rank-num">${s.rank}</span><div><b>${esc(s.name)}</b><small class="subline">${esc(s.department)} · ${esc(s.year)}</small></div><b class="green-text">${s.points}</b></div>`).join("")||'<div class="empty-state">No task points yet.</div>'}catch(e){}}
async function loadAdminActivityPoints(){try{const d=await api("/api/admin/activity-points");$("adminActivityPoints").innerHTML=d.students.length?`<div class="table-wrap"><table class="data-table"><thead><tr><th>Rank</th><th>Student</th><th>Dept / Year</th><th>Register</th><th>Points</th></tr></thead><tbody>${d.students.map(s=>`<tr><td>#${s.rank}</td><td><b>${esc(s.name)}</b></td><td>${esc(s.department)} · ${esc(s.year)}</td><td>${esc(s.register_no)}</td><td><b class="green-text">${s.points}</b></td></tr>`).join("")}</tbody></table></div>`:'<div class="empty-state">No activity yet.</div>'}catch(e){showToast(e.message)}}
async function loadAdminTaskLeaderboard(){try{const d=await api("/api/admin/tasks/leaderboard");$("adminTaskLeaderboard").innerHTML=d.leaderboard.length?`<div class="table-wrap"><table class="data-table"><thead><tr><th>Rank</th><th>Student</th><th>Dept / Year</th><th>Points</th></tr></thead><tbody>${d.leaderboard.map(s=>`<tr><td>#${s.rank}</td><td><b>${esc(s.name)}</b></td><td>${esc(s.department)} · ${esc(s.year)}</td><td><b class="green-text">${s.points}</b></td></tr>`).join("")}</tbody></table></div>`:'<div class="empty-state">No task points yet.</div>'}catch(e){showToast(e.message)}}
function slotsSection(which,btn){document.querySelectorAll("#slotSeg .seg-btn").forEach(x=>x.classList.remove("active"));btn.classList.add("active");["slotSettings","slotRegister","slotNoShows"].forEach(id=>$(id).classList.add("hidden"));$(which==="settings"?"slotSettings":which==="register"?"slotRegister":"slotNoShows").classList.remove("hidden");if(which==="settings")loadAdminSlotSettings();if(which==="register")loadAdminSlotRegister();if(which==="noshows")loadAdminSlotNoShows()}
async function loadAdminSlotSettings(){try{const d=await api("/api/admin/slots/settings");window.__slotDays=d.days||[];$("slotOpenTime").value=d.open_time;$("slotTargetLabel").textContent=niceDate(d.target_date)+" · "+(d.window_open?"open":"closed");$("slotAdminStatus").textContent=`Window: ${d.window_open?"OPEN":"closed"} · ${d.booked}/${d.capacity} booked for ${d.target_date}. Opens daily at ${d.open_time}.`;const sel=$("slotRegisterDate");sel.innerHTML='<option value="">Select a date</option>'+d.days.map(x=>`<option value="${x.date}">${x.date}${x.open?"":" (cancelled)"}</option>`).join("");$("slotNoShowDate").innerHTML='<option value="">Select a date</option>'+d.days.map(x=>`<option value="${x.date}">${x.date}</option>`).join("");const today=d.days[0]?d.days[0].date:d.target_date;if(d.days.length){sel.value=today;$("slotNoShowDate").value=today;}loadAdminSlotBookings(today)}catch(e){showToast(e.message)}}
async function loadAdminSlotBookings(date){try{const d=await api(`/api/admin/slots/register?date=${date}`);const b=d.rows.filter(r=>r.booked);$("adminSlotBookings").innerHTML=b.length?`<div class="table-wrap"><table class="data-table"><thead><tr><th>#</th><th>Student</th><th>Course</th><th>Level</th><th>Status</th><th>Score</th></tr></thead><tbody>${b.map((r,i)=>`<tr><td>${i+1}</td><td><b>${esc(r.name)}</b><small class="subline">${esc(r.register_no)}</small></td><td>${esc(r.course)}</td><td>${esc(r.level)}</td><td>${r.status?`<span class="badge ${r.status==="completed"?"badge-ok":r.status==="not_attended"?"badge-err":"badge-warn"}">${esc(r.status)}</span>`:'<span class="badge badge-warn">not reported</span>'}</td><td>${r.score!==undefined&&r.score!==""?r.score:"—"}</td></tr>`).join("")}</tbody></table></div>`:'<div class="empty-state">No bookings for this date.</div>'}catch(e){showToast(e.message)}}
async function updateSlotSettings(){const ot=$("slotOpenTime").value||"18:00";try{await api("/api/admin/slots/settings",{method:"POST",headers:{"Content-Type":"application/json"},body:JSON.stringify({open_time:ot})});showToast("Open time updated ✓");loadAdminSlotSettings()}catch(e){showToast(e.message)}}
async function cancelSlotToday(){try{await api("/api/admin/slots/settings",{method:"POST",headers:{"Content-Type":"application/json"},body:JSON.stringify({cancel_today:true})});showToast("Today's window cancelled — reopens tomorrow.");loadAdminSlotSettings()}catch(e){showToast(e.message)}}
async function reopenSlotToday(){try{await api("/api/admin/slots/settings",{method:"POST",headers:{"Content-Type":"application/json"},body:JSON.stringify({reopen_today:true})});showToast("Window reopened.");loadAdminSlotSettings()}catch(e){showToast(e.message)}}
async function loadAdminSlotRegister(){const date=$("slotRegisterDate").value||(window.__slotDays&&window.__slotDays[0]?window.__slotDays[0].date:"");if(!date)return;try{const d=await api(`/api/admin/slots/register?date=${date}`);$("adminSlotRegister").innerHTML=`<p class="muted">${d.booked_count} booked · ${d.reported} reported · ${d.total} students</p>`+`<div class="table-wrap"><table class="data-table"><thead><tr><th>Student</th><th>Register</th><th>Dept / Year</th><th>Course</th><th>Level</th><th>Status</th><th>Score</th></tr></thead><tbody>${d.rows.map(r=>{const status=r.status?`<span class="badge ${r.status==="completed"?"badge-ok":r.status==="not_attended"?"badge-err":"badge-warn"}">${esc(r.status)}</span>`:(r.booked?'<span class="badge badge-warn">not reported</span>':'<span class="muted">not booked</span>');return `<tr class="${r.no_show?"row-noshows":""}"><td><b>${esc(r.name)}</b></td><td>${esc(r.register_no)}</td><td>${esc(r.department)} · ${esc(r.year)}</td><td>${esc(r.course)||"—"}</td><td>${esc(r.level)||"—"}</td><td>${status}</td><td>${r.score!==""?r.score:"—"}</td></tr>`}).join("")}</tbody></table></div>`}catch(e){showToast(e.message)}}
function exportSlot(scope){const date=$("slotRegisterDate").value||(window.__slotDays&&window.__slotDays[0]?window.__slotDays[0].date:"");window.location.href=`/api/admin/slots/export?scope=${scope}&date=${date}`}
async function loadAdminSlotNoShows(){const date=$("slotNoShowDate").value||(window.__slotDays&&window.__slotDays[0]?window.__slotDays[0].date:"");if(!date)return;try{const d=await api(`/api/admin/slots/noshows?date=${date}`);const list=d.names.length?d.names.map(n=>`<div class="clearance-row"><span class="badge badge-err">NO-SHOW</span><div><b>${esc(n)}</b></div></div>`).join(""):'<div class="empty-state">Everyone attended their booked slots.</div>';const copy=d.names.length?`<div class="whatsapp-box"><textarea id="waMessage" rows="5" readonly>${esc(d.message)}</textarea><div class="row-actions"><button class="primary-btn sm" onclick="copySlotMessage()">Copy message</button><a class="ghost-btn sm" href="${esc(d.wa_link)}" target="_blank" rel="noopener">Open WhatsApp ↗</a></div></div>`:'';$("adminSlotNoShows").innerHTML=list+copy}catch(e){showToast(e.message)}}
function copySlotMessage(){const t=$("waMessage");t.select();try{navigator.clipboard.writeText(t.value)}catch{}t.setSelectionRange(0,t.value.length);showToast("Message copied.")}
function renderAdminStats(d){const s=d.stats;const items=[["Students",s.total_students],["Active",s.active_students],["Plans today",s.plans_today],["PS reports today",s.ps_today],["Pending verification",s.pending_verifications],["Open issues",s.open_issues]];$("realAdminStats").innerHTML=items.map(x=>`<div class="stat"><span>${x[0]}</span><b>${x[1]}</b><small>Live database</small></div>`).join("")}
function renderAdminCourses(d){const rows=d.courses||[];$("adminCourses").innerHTML=rows.length?`<div class="admin-course-grid">${rows.map(c=>`<div class="course-card"><div class="course-card-head"><div><strong>${esc(c.course)}</strong><span>${c.completed_levels} verified levels · ${c.students} students</span></div><b class="green-text">VERIFIED</b></div><div class="bar"><i style="width:${Math.min(100,c.completed_levels/Math.max(1,rows[0].completed_levels)*100)}%"></i></div></div>`).join("")}</div>`:'<div class="empty-state">No verified course activity yet.</div>'}
function renderAdminLeaderboard(rows){$("adminLeaderboard").innerHTML=`<div class="table-wrap"><table class="data-table"><thead><tr><th>Rank</th><th>Student</th><th>Progress</th><th>Levels</th><th>Streak</th></tr></thead><tbody>${(rows||[]).map(r=>`<tr><td>#${r.rank}</td><td><b>${esc(r.name)}</b><small class="subline">${esc(r.department)} · ${esc(r.year)}</small></td><td><b class="green-text">${r.progress}%</b></td><td>${r.levels}</td><td>🔥 ${r.streak}</td></tr>`).join("")}</tbody></table></div>`}
async function loadAdmin(){try{const d=await api("/api/admin/dashboard");renderAdminStats(d);await renderAdminSupport()}catch(e){}}
async function adminResetPassword(id){const p=prompt("Set a temporary password (8+ characters):");if(!p)return;try{const d=await api(`/api/admin/student/${id}/reset-password`,{method:"POST",headers:{"Content-Type":"application/json"},body:JSON.stringify({password:p})});showToast(d.message+" ✓")}catch(e){showToast(e.message)}}
async function adminChangeName(id,reg,current){const n=prompt("Correct student name:",current);if(!n)return;try{const d=await api(`/api/admin/student/${id}/update-name`,{method:"POST",headers:{"Content-Type":"application/json"},body:JSON.stringify({name:n})});showToast(d.message+" ✓");adminOpenSearch(id,reg)}catch(e){showToast(e.message)}}
async function adminAcademic(id,reg,program,department,year,batch){const p=prompt("Program (B.E. / B.Tech):",program);if(!p)return;const dep=prompt("Department (CSE/ECE/EEE/MECH/CIVIL/IT/AIDS/CSBS/AIML):",department);if(!dep)return;const y=prompt("Year (I Year/II Year/III Year/IV Year):",year);if(!y)return;const b=prompt("Batch:",batch);if(!b)return;try{const d=await api(`/api/admin/student/${id}/update-academic`,{method:"POST",headers:{"Content-Type":"application/json"},body:JSON.stringify({program:p,department:dep,year:y,batch:b})});showToast(d.message+" ✓");adminOpenSearch(id,reg)}catch(e){showToast(e.message)}}
async function adminToggleStatus(id,reg,current){const next=current==='Active'?'Inactive':'Active';if(!confirm(`${next} this student account?`))return;try{const d=await api(`/api/admin/student/${id}/status`,{method:"POST",headers:{"Content-Type":"application/json"},body:JSON.stringify({status:next})});showToast(d.message+" ✓");adminOpenSearch(id,reg);loadAdmin()}catch(e){showToast(e.message)}}
async function renderAdminSupport(){try{const d=await api("/api/admin/support");$("adminSupport").innerHTML=(d.requests||[]).map(r=>`<div class="support-admin"><div><b>${esc(r.category)}</b><span>${esc(r.name)} · ${esc(r.register_no)}</span><p>${esc(r.message)}</p><small>${niceDate((r.created_at||"").slice(0,10))}</small>${r.admin_note?`<small>Note: ${esc(r.admin_note)}</small>`:""}</div><div class="support-control"><span class="badge ${r.status.toLowerCase().replaceAll(" ","-")}">${esc(r.status)}</span><select onchange="updateSupport(${r.id},this.value)"><option ${r.status==='Open'?'selected':''}>Open</option><option ${r.status==='In Progress'?'selected':''}>In Progress</option><option ${r.status==='Resolved'?'selected':''}>Resolved</option></select><input placeholder="Admin note" onchange="updateSupportNote(${r.id},this.value)"></div></div>`).join("")||'<div class="empty-state">No support requests.</div>'}catch(e){showToast(e.message)}}
async function updateSupport(id,status,note=""){try{await api(`/api/admin/support/${id}`,{method:"POST",headers:{"Content-Type":"application/json"},body:JSON.stringify({status,admin_note:note})});showToast("Support updated ✓");renderAdminSupport()}catch(e){showToast(e.message)}}
function updateSupportNote(id,note){const row=document.querySelector(`[data-support-id="${id}"]`);updateSupport(id,"In Progress",note)}

applyTheme();
document.addEventListener("input",function(e){if(!e.target.closest("#plannerGrid"))return;const cells=document.querySelectorAll(".planner-grid .planner-cell");let count=0;cells.forEach(c=>{const inp=c.querySelector("input[id^='h']");const sel=c.querySelector("select[id^='v']");const hasTask=inp&&inp.value.trim();const hasVenue=sel&&sel.value;if(hasTask&&hasVenue)c.classList.add("has-task");else c.classList.remove("has-task");if(hasTask)count++});const pct=Math.round(count/7*100);const rf=$("planReadyFill");if(rf)rf.style.width=pct+"%";const rl=$("plannerReady")?.querySelector("span");if(rl)rl.textContent=`${count}/7 hours planned`});
window.addEventListener("load",async()=>{buildCourseOptions("verifyCourse");checkDevSkip();try{const s=await api("/api/session");if(s.logged_in){if(s.role==='student'){currentStudent=s.student;openStudent()}else openAdmin()}}catch{}});
